import pg from 'pg';

const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL,
  max: 3,
  idleTimeoutMillis: 10000,
  connectionTimeoutMillis: 8000,
});

export async function query(text, params) {
  const result = await pool.query(text, params);
  return result.rows;
}

// The HMAC key lives only in the database, generated by the database itself.
let cachedKey = null;
export async function hmacKey() {
  if (cachedKey) return cachedKey;
  const rows = await query('SELECT value FROM streamix.settings WHERE key = $1', ['code_hmac_key']);
  if (!rows.length || rows[0].value.length !== 32) throw new Error('Missing Streamix HMAC key');
  cachedKey = rows[0].value;
  return cachedKey;
}
